"""No inferred Dense kernel times: measured common boundaries and exact-input diagnostics."""
import csv,hashlib,json,shutil,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'outputs/dense_sparse_comparison_20261104'
def table(rows,keys):
 def value(x):return f'{x:.6f}' if isinstance(x,float) else str(x)
 return '\n'.join(['| '+' | '.join(keys)+' |','| '+' | '.join(['---']*len(keys))+' |']+['| '+' | '.join(value(r.get(k,'—')) for k in keys)+' |' for r in rows])
def csvwrite(name,rows):
 with (OUT/name).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(dict.fromkeys(k for r in rows for k in r)));w.writeheader();w.writerows(rows)
def main():
 ds={m:json.loads((OUT/m/'result.json').read_text()) for m in ['dense','v8','p0','beta']};assert (OUT/'completion.json').exists()
 inputs=[d['input'] for d in ds.values()];assert all(d['image_paths']==inputs[0]['image_paths'] and d['frame_indices']==inputs[0]['frame_indices'] and d['shape']==inputs[0]['shape'] for d in inputs)
 assert all(Path(d['input']['checkpoint']).resolve()==Path(inputs[0]['checkpoint']).resolve() for d in ds.values())
 timing=[];ops=[];per_layer=[];account=[]
 for method,d in ds.items():
  mon=json.loads((OUT/f'{method}_monitor.json').read_text());assert mon['returncode']==0 and not mon['foreign_gpu_pids'] and not mon['same_gpu_overlap_detected'] and mon['max_simultaneous_gpu_applications']==1
  timing.append(dict(method=method,warmed_median_s=d['median_seconds'],sample_min_s=min(x['seconds'] for x in d['samples']),sample_max_s=max(x['seconds'] for x in d['samples']),dense_speedup=ds['dense']['median_seconds']/d['median_seconds'],peak_allocated_gib=max(x['peak_allocated_gib'] for x in d['samples']),peak_reserved_gib=max(x['peak_reserved_gib'] for x in d['samples'])))
  for k,v in d['profile']['groups'].items():ops.append(dict(method=method,operation=k,**v))
  events=d['profile']['events'];by={x['id']:x for x in events};globals=[x for x in events if x['operation']=='global_attention']
  def inside(row,ancestor):
   while row['parent'] is not None:
    row=by[row['parent']]
    if row['id']==ancestor:return True
   return False
  common_names=['global_qkv','global_qk_norm','global_rope','global_output_projection']
  core_names=['dense_global_core','sparse_core_fused_evidence']
  for layer,glob in enumerate(globals):
   children=[x for x in events if inside(x,glob['id'])]
   common=sum(x['exclusive_seconds'] for x in children if x['operation'] in common_names);core=sum(x['exclusive_seconds'] for x in children if x['operation'] in core_names)
   per_layer.append(dict(method=method,layer=layer,global_attention_s=glob['inclusive_seconds'],qkv_norm_rope_proj_s=common,attention_core_s=core,other_global_s=glob['inclusive_seconds']-common-core))
  rows=[x for x in per_layer if x['method']==method];glob=sum(x['global_attention_s'] for x in rows);common=sum(x['qkv_norm_rope_proj_s'] for x in rows);core=sum(x['attention_core_s'] for x in rows)
  account.append(dict(method=method,profile_full_s=d['profile']['wall_seconds'],global_attention_s=glob,common_qkv_norm_rope_proj_s=common,attention_core_s=core,other_global_s=glob-common-core,outside_global_s=d['profile']['wall_seconds']-glob))
 common=[]
 for operation in ['image_backbone','frame_attention','ffn','block_norm','global_qkv','global_qk_norm','global_output_projection','camera_head','depth_head','point_head']:
  r=dict(operation=operation)
  for m,d in ds.items():r[m+'_s']=d['profile']['groups'].get(operation,{}).get('inclusive_seconds',0.)
  common.append(r)
 diag=json.loads((ROOT/'outputs/beta_regression_diagnostic_v3_20261104/result.json').read_text());same=json.loads((ROOT/'outputs/attention_same_qkv_20261104/result.json').read_text());assert diag['complete'] and same['complete']
 sampled=dict(dense_core_s=sum(x['dense_core_seconds'] for x in same['rows']),sparse_core_s=sum(x['sparse_core_fused_evidence_seconds'] for x in same['rows']),sparse_executor_s=sum(x['sparse_executor_seconds'] for x in same['rows']))
 sampled.update(dense_over_sparse_core=sampled['dense_core_s']/sampled['sparse_core_s'],dense_over_sparse_executor=sampled['dense_core_s']/sampled['sparse_executor_s'])
 summary=dict(complete=True,timings=timing,accounting=account,common=common,same_qkv_sample=sampled,quality_diagnostic=diag,paired_gpu=7,quality_retuning=False,changed_method_quality='v8_p0_quality_v2_20261104 evaluated separately',quality_scores_source='historical complete matched18-scene controls and beta experiment,not regenerated by timing runs')
 (OUT/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
 for name,rows in [('timing.csv',timing),('operations.csv',ops),('per_layer.csv',per_layer),('accounting.csv',account),('common.csv',common),('same_qkv_per_layer.csv',same['rows'])]:csvwrite(name,rows)
 refs=OUT/'quality_references';refs.mkdir(exist_ok=True)
 base=Path('/tmp/sparse-vggt-beta-gridmass-20261104/outputs/beta_gridmass_20261104')
 quality=json.loads((base/'summary.json').read_text());shutil.copyfile(base/'summary.json',refs/'beta_campaign_summary.json');shutil.copyfile(base/'macro.csv',refs/'historical_controls_and_beta_macro.csv')
 qrows=[]
 for r in quality['macro']:
  if r['method'] in ['dense','v8','beta_gridmass']:
   qrows.append(dict(dataset=r['dataset'],method=r['method'],scenes=r['scenes'],auc03_percent=r['auc03']*100,auc30_percent=r['auc30']*100,acc_m=r['acc'],comp_m=r['comp'],cd_m=r['cd'],f1_percent=r['f1']*100))
 csvwrite('quality_references.csv',qrows)
 layer1=next(r for r in diag['rows'] if r['layer']==1)
 body=['# Dense versus v8/P0/beta: matched runtime and regression diagnosis','',
 'All methods: identical heads128 frame paths, checkpoint, preprocessing, BF16, TF32 disabled, RTX5090 D GPU7, one CUDA process per physical GPU with CPU-only locks/monitors. One cold/warmup + three complete-forward measurements, followed by a separate instrumented forward. GT quality and checkpoint/image loading excluded. This rerun of unchanged Dense/v8 is explicitly authorized by the user request to compare with the original model. GPU4–6 may run independent processes; physical GPU7 remains exclusive. No clock locking is claimed. Samples and ranges are preserved, including beta timing variation.','',
 table(timing,['method','warmed_median_s','sample_min_s','sample_max_s','dense_speedup','peak_allocated_gib','peak_reserved_gib']),'',
 '## Shared operations and added sparse work','',
 'Seconds below are from the separate profile, not partitions of the warmed median. Each global layer is decomposed into named QKV/Norm/RoPE/output projection, core, and remaining global work. outside_global includes the unchanged backbone, frame Attention, ALL FFNs including global block FFNs, norms/residuals, heads, allocator/host gaps and any uninstrumented work. It is an accounting residual, not an extra sparse stage and not an identical fixed constant across methods.','',
 table(account,['method','profile_full_s','common_qkv_norm_rope_proj_s','attention_core_s','other_global_s','outside_global_s']),'',
 table(common,['operation','dense_s','v8_s','p0_s','beta_s']),'',
 'The v8 added stages are Value/cluster updates, geometry and pooling, coarse/history observation, history cache production/consumption, eligibility gates, state losses, budget solve, Key packing, mass transfer, diagnostics and execution preparation. None is needed by original Dense SDPA. sparse_execution_wrapper exclusive time covers sorting/gathers/offset preparation and launch/allocator gaps, while sparse_grid_reduce is an added per-Grid statistics reduction. The sparse core also writes probes and Grid evidence, so it is not a pure QK/Softmax/AV-only kernel. Tiny reshapes/residual framework work exists on both paths and is not proven wholly sparse-only. Exclusive accounting avoids double counting.','',
 'Shared tensor operations were not found to be uniformly slower. Reported named times measure both paths directly; no historical Dense-minus-current-residual inference is used. Differences in allocation, layout, launch gaps and separate forward trajectories can affect common times. Shared RoPE is wrapped repeatedly because global modules share one object; only exclusive events are summed in accounting, including frame uses outside the global boundary. The additional hook dispatch cost means profile wall is diagnostic; uninstrumented medians are authoritative.','',
 '## Is the sparse core faster?','',
 'Complete-profile Dense global core is the native SDPA call, summed over24 layers. Sparse core is the actual fused AV+Grid/probe kernel, excluding wrapper sorting and Grid reduction. Compare attention_core_s above for the full-input native trajectories. Sparse core savings must pay all additional global work before an end-to-end gain is possible.','',
 'To separate trajectory/input differences, a second diagnostic replays the SAME Q/K/V from the first64-group window (2048 queries) of every beta layer, including Specials, original compensation and original probes. Native full-Key Dense SDPA and sparse executor are warmed and timed three times independently. These summed window medians are NOT whole-model timings; L0 is slower sparse.','',table([sampled],list(sampled)),'',
 '## Why beta quality collapses','',
 'Same-input shadow analysis uses the actual beta trajectory: first4 query groups/window0, original four probes and all heads. The shadow v8 estimator sees the SAME previous sparse support, raw unweighted logits, current Q/K, clustering and coarse observations. Alternate outputs do not feed the network. Priors are compared with exact current-QK Dense probabilities; L1/KL normalize patch mass only for comparing distributions. Other reported support masses are original full-normalization patch mass.','',
 'At L1: beta assigns previous selected Keys mass '+str(layer1['beta_previous_support_mass'])+', exact Dense '+str(layer1['dense_previous_support_mass'])+', and shadow v8 '+str(layer1['shadow_v8_previous_support_mass'])+'. Prior distribution L1 error: beta '+str(layer1['beta_prior']['l1_mean'])+', v8 '+str(layer1['shadow_v8_prior']['l1_mean'])+'.','',
 'The actual sparse probability already contains population/mass-transfer compensation: P_sparse(i)=exp(raw_i+bias_i)/Z_sparse. It therefore estimates represented mass on emitted Keys, not the unweighted individual-Key conditional cached by v8. Passing that value as an individual-Key prior reuses compensation in the next layer. Global normalization and per-Grid conditional normalization are not interchangeable, even if total current Grid mass is conserved.','',
 'The new hard cap can assign all current Grid mass to selected Keys, leaving exactly zero prior for unobserved members. At L1 the sampled beta prior zero fraction is '+str(layer1['beta_prior_zero_fraction'])+'; shadow v8 has zero fraction '+str(layer1['shadow_v8_prior_zero_fraction'])+'. A zero-prior Key can still be emitted by Exact/History. Existing mass transfer computes weight=max(assigned_mass/max(own_prior,1e-30),1). An owner with zero own prior and positive assigned mass produces a huge compensation. The sampled L1 selected zero-prior fraction is '+str(layer1['selected_prior_zero_fraction'])+', maximum compensation log-bias '+str(layer1['compensation_logbias_max'])+' (weight about exp(61), not a normal cluster-size factor).','',
 'Those biased probabilities become highly concentrated BEFORE cache rounding: at L1 '+str(layer1['sparse_probability_below_fp16_halfsubnormal_fraction'])+' of valid per-probe cache entries are below half the smallest positive FP16 subnormal; the FP32 zero fraction is '+str(layer1['sparse_probability_fp32_zero_fraction'])+'. FP16 storage then makes them exactly zero; shadow v8 Grid-conditional cache has zero fraction '+str(layer1['v8_conditional_cache_zero_fraction'])+'. This feeds the next layer and creates a feedback loop. Merely using FP32 cache would preserve tiny values but would not fix the wrong represented-mass semantics or huge log-bias.','',
 'Sparse AV is independently compared with FP32 exact softmax on the SAME emitted support and compensation. Maximum sampled mean relative L2 is '+str(max(x.get('sparse_core_vs_same_support_fp32_relative_l2_mean',0) for x in diag['rows']))+'. This supports estimator/compensation failure, not an observed gross mask-execution bug; it is a sampled check, not proof that every kernel case is correct. The chain above is directly observed, but relative causal contributions have not been isolated by new full-dataset interventions. No probability floor, retention, confidence or quality gate was tuned against test truth.','',
 '## Existing complete geometry results','',
 'These are reused complete historical matched-input controls and the already-frozen beta campaign, NOT quality measured by the timing diagnostics. All7 7Scenes scenes128frames and all11 ETH3D scenes14–76frames; equal-scene macro; AUC/F1 percentages, distances unsquared metres, CD=(ACC+Comp)/2. Pose+recon_unposed. Threshold/voxel7Scenes0.05/0.0078125m,ETH3D0.25/0.0390625m. Full per-scene raw metrics are in the beta campaign remote commit7abc8442.','',table(qrows,list(qrows[0])),'',
 'P0 is a separate execution prototype of original v8, not beta. Initial P0 kernels preserve sampled Key order/owners but are slower than their reference kernels; they are not promoted to the default path. All23 changed layers receive a captured-vs-eager routing check, and complete P0 geometry evaluation is recorded separately. This first P0 prototype reuses geometry across neighboring Query Groups; it does NOT claim to have implemented the document\'s Cluster–Grid sufficient-statistics decomposition.','',
 'Every timing/kernel/estimator diagnostic retains all six quality fields as unavailable with a concrete reason. End-to-end Dense speedup belongs only to the matched full-forward medians above; operator ratios and historical geometry rows must not be used as substitutes.']
 (OUT/'report.md').write_text('\n'.join(body)+'\n');print(json.dumps(dict(complete=True,timing=timing,accounting=account,same_qkv_sample=sampled),indent=2))
if __name__=='__main__':main()
